//! `num` against `tests/vectors/num/num.json` (generated by `gen_num.py` from
//! `shortwin_sim.py` v0.4.1 helpers). Worked example of the vector convention.

mod common;

use common::Dec;
use serde::Deserialize;
use shortwin_math::MathError;
use shortwin_math::num::{
    Rounding, U256, mul_bps_u64, mul_div, mul_div_i128, sqrt_u128, sqrt_u256,
};

#[derive(Deserialize)]
struct File {
    generator: String,
    mul_div: Vec<MulDiv<u128>>,
    mul_div_i128: Vec<MulDiv<i128>>,
    fee_ceil: Vec<FeeCeil>,
    isqrt: Vec<Isqrt>,
}

/// `floor`/`ceil` are `null` when the result does not fit the output type.
#[derive(Deserialize)]
#[serde(bound(deserialize = "T: std::str::FromStr, T::Err: std::fmt::Display"))]
struct MulDiv<T> {
    a: Dec<T>,
    b: Dec<u128>,
    d: Dec<u128>,
    floor: Option<Dec<T>>,
    ceil: Option<Dec<T>>,
}

#[derive(Deserialize)]
struct FeeCeil {
    x: Dec<u64>,
    bps: Dec<u64>,
    fee: Option<Dec<u64>>,
}

#[derive(Deserialize)]
struct Isqrt {
    x: Dec<U256>,
    floor: Dec<u128>,
    /// `isqrt⁺` (`shortwin_sim.isqrt_ceil`, the `reprice` root; ECON §2.1); `null` above
    /// `u128`.
    ceil: Option<Dec<u128>>,
}

fn expect<T>(v: &Option<Dec<T>>) -> Result<T, MathError>
where
    T: Copy,
{
    v.as_ref().map(|d| d.0).ok_or(MathError::Overflow)
}

#[test]
fn num_matches_sim() {
    let f: File = common::load_vectors("num", "num.json");
    assert_eq!(f.generator, "gen_num.py");
    assert!(!f.mul_div.is_empty() && !f.mul_div_i128.is_empty());

    for c in &f.mul_div {
        let (a, b, d) = (c.a.0, c.b.0, c.d.0);
        assert_eq!(
            mul_div(a, b, d, Rounding::Floor),
            expect(&c.floor),
            "{a}·{b}/{d}"
        );
        assert_eq!(
            mul_div(a, b, d, Rounding::Ceil),
            expect(&c.ceil),
            "⌈{a}·{b}/{d}⌉"
        );
    }
    for c in &f.mul_div_i128 {
        let (a, b, d) = (c.a.0, c.b.0, c.d.0);
        assert_eq!(
            mul_div_i128(a, b, d, Rounding::Floor),
            expect(&c.floor),
            "{a}·{b}/{d}"
        );
        assert_eq!(
            mul_div_i128(a, b, d, Rounding::Ceil),
            expect(&c.ceil),
            "⌈{a}·{b}/{d}⌉"
        );
    }
    // ECON §3.1: every fee component is ⌈n·φ/10⁴⌉ (`fee_ceil` in the sim).
    for c in &f.fee_ceil {
        assert_eq!(
            mul_bps_u64(c.x.0, c.bps.0, Rounding::Ceil),
            expect(&c.fee),
            "fee_ceil({}, {})",
            c.x.0,
            c.bps.0
        );
    }
    for c in &f.isqrt {
        let x = c.x.0;
        assert_eq!(x.isqrt(), c.floor.0, "isqrt({x})");
        assert_eq!(sqrt_u256(x, Rounding::Floor), Ok(c.floor.0), "isqrt({x})");
        assert_eq!(sqrt_u256(x, Rounding::Ceil), expect(&c.ceil), "isqrt⁺({x})");
        if let Some(x) = x.to_u128() {
            assert_eq!(sqrt_u128(x, Rounding::Floor), c.floor.0, "isqrt({x})");
            assert_eq!(
                Ok(sqrt_u128(x, Rounding::Ceil)),
                expect(&c.ceil),
                "isqrt⁺({x})"
            );
        }
    }
}
